import {analyzeVin,decodeReport,vinURL} from './vin.js';
export function openVinDecoder({panel,esc,read,save,copy,useVehicle}){
 let history=read('vin-cache',[]),current=null,serial=0,pending=false;
 panel(`<span class="dialog-category">VIN DECODER</span><h2>Start with the vehicle.</h2><p>Identify the vehicle and engine before your parts lookup. Manufacturer-reported vehicle data; missing fields remain unknown.</p><form id="vinForm"><label class="note-label" for="vinInput">17-character VIN</label><div class="detail-filter"><input id="vinInput" maxlength="30" autocomplete="off" autocapitalize="characters" spellcheck="false" placeholder="Enter or paste the complete VIN"></div><label class="note-label" for="vinYear">Model year, if known (optional)</label><div class="detail-filter"><input id="vinYear" type="number" min="1981" max="2100" placeholder="Helps resolve repeating year codes"></div><p id="vinValidation" role="status"></p><button class="primary" id="vinSubmit" type="submit">Decode VIN ↗</button></form><p class="vin-privacy">Internet is required for a new lookup. Your VIN and optional model year are sent to the vehicle-data provider. It does not send your notes or worksheet. Successful and partial lookups are saved on this device for offline reference.</p><div id="vinResult" aria-live="polite"></div><div id="vinHistory"></div><p>VIN data does not establish exact parts fitment, paint/trim codes, axle ratio, production options or service supersessions. Confirm those in Ford’s catalog. <a href="https://vpic.nhtsa.dot.gov/decoder/" target="_blank" rel="noopener">Data source: NHTSA vPIC ↗</a></p>`);
 const $=s=>document.querySelector(s);
 function renderHistory(){if(!$('#vinHistory'))return;$('#vinHistory').innerHTML=`<h3>Recent decoded vehicles</h3>${history.length?history.map((r,i)=>`<button class="vin-history secondary" data-vin-history="${i}"><strong>${esc(r.title)}</strong><code>${esc(r.vin)}</code>${r.warning?'<span>Partial / warnings</span>':''}</button>`).join('')+'<button class="secondary" id="clearVinHistory">Clear decoded history</button>':'<p>No saved VIN lookups yet.</p>'}`;$('#vinHistory').onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.vinHistory!==undefined){const r=history[+b.dataset.vinHistory];$('#vinInput').value=r.vin;$('#vinYear').value=r.modelYearHint||'';renderResult(r,true);}else if(b.id==='clearVinHistory'&&confirm('Clear saved VIN results from this device?')){if(save('vin-cache',[])){history=[];renderHistory();}}};}
 function renderResult(r,cached){if(!$('#vinResult'))return;current=r;$('#vinResult').innerHTML=`<div class="vin-vehicle"><span class="eyebrow">${cached?'SAVED LOOKUP · ':'VEHICLE RESULT · '}${esc(r.decodedAt.slice(0,10))}</span><h3>${esc(r.title)}</h3><code>${esc(r.vin)}</code>${r.warning?`<p class="detail-note">Partial decode / source warnings: ${esc(r.errorText||r.errorCode)}${r.suggestedVin?'<br>Source suggested VIN: '+esc(r.suggestedVin)+' (not applied automatically)':''}</p>`:'<p class="vin-ok">The provider returned no decoding errors.</p>'}<table class="stats-table">${r.fields.map(f=>`<tr><td>${esc(f.label)}</td><td>${esc(f.value)}</td></tr>`).join('')}</table><p>Unlisted details were not supplied by the source.</p><div class="tools-actions"><button class="primary" id="vinToWorksheet">Use in worksheet</button><button class="secondary" id="copyVinResult">Copy vehicle details</button></div></div>`;$('#vinToWorksheet').onclick=()=>useVehicle(r);$('#copyVinResult').onclick=()=>copy([r.title,r.vin,...r.fields.map(f=>f.label+': '+f.value),r.warning?'Source warnings: '+r.errorText:'','Source: NHTSA vPIC · '+r.decodedAt.slice(0,10),'Confirm exact part fitment by VIN.'].filter(Boolean).join('\n'));}
 $('#vinInput').oninput=()=>{const a=analyzeVin($('#vinInput').value);$('#vinValidation').textContent=!$('#vinInput').value?'':!a.valid?a.error:a.warning||'VIN format and check digit pass.';};
 async function nativeLookup(vin,year,id){return new Promise((resolve,reject)=>{const timeout=setTimeout(()=>{window.removeEventListener('parts-vin-result',handler);reject(Error('NHTSA lookup timed out. Please try again.'));},18000);const handler=e=>{if(e.detail.id!==id)return;clearTimeout(timeout);window.removeEventListener('parts-vin-result',handler);e.detail.error?reject(Error(e.detail.error)):resolve(e.detail.data);};window.addEventListener('parts-vin-result',handler);window.PartsNative.decodeVin(vin,year,id);});}
 $('#vinForm').onsubmit=async e=>{
  e.preventDefault();if(pending)return;const a=analyzeVin($('#vinInput').value);if(!a.valid){$('#vinValidation').textContent=a.error;return;}
  const year=$('#vinYear').value.trim();if(year&&(!/^\d{4}$/.test(year)||+year<1981||+year>2100)){$('#vinValidation').textContent='Use a model year between 1981 and 2100, or leave it blank.';return;}
  $('#vinInput').value=a.vin;$('#vinValidation').textContent=a.warning||'Looking up vehicle…';const cached=history.find(r=>r.vin===a.vin&&(r.modelYearHint||'')===year);
  if(!navigator.onLine&&cached){renderResult(cached,true);$('#vinValidation').textContent='Offline: showing the saved lookup.';return;}
  pending=true;$('#vinSubmit').disabled=true;$('#vinSubmit').textContent='Decoding…';const id=String(Date.now())+'-'+(++serial);
  try{
   let payload;if(typeof window.PartsNative?.decodeVin==='function')payload=await nativeLookup(a.vin,year,id);
   else{const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),15000);try{const response=await fetch(vinURL(a.vin,year),{signal:controller.signal});if(!response.ok)throw Error('NHTSA is unavailable (HTTP '+response.status+'). Try again.');payload=await response.json();}finally{clearTimeout(timer);}}
   const r={...decodeReport(payload,a.vin),modelYearHint:year};if(!a.checksumValid&&!r.warning){r.warning=true;r.errorText=a.warning;}
   const next=[r,...history.filter(x=>x.vin!==r.vin||x.modelYearHint!==year)].slice(0,15);if(save('vin-cache',next))history=next;
   renderResult(r,false);renderHistory();if($('#vinValidation'))$('#vinValidation').textContent=r.warning?'Review the source warnings below.':'Vehicle decoded. Missing specifications are not inferred.';
  }catch(err){if($('#vinValidation'))$('#vinValidation').textContent=(err.name==='AbortError'?'NHTSA lookup timed out.':err.message||'Lookup unavailable.')+(cached?' Showing the last saved result.':' Try again, or use the official decoder link below.');if(cached)renderResult(cached,true);}
  finally{pending=false;if($('#vinSubmit')){$('#vinSubmit').disabled=false;$('#vinSubmit').textContent='Decode VIN ↗';}}
 };
 renderHistory();
}

